protocol Described {                      // the descriptor interface
    associatedtype Payload                // associatedtype = the traits payload
    func key() -> UInt64
}
extension Frame: Described {              // conformance binds the description
    typealias Payload = Bytes
    func key() -> UInt64 { crc }
}
extension Array: Described where Element: Described {          // partial specialization
    typealias Payload = Element.Payload
    func key() -> UInt64 { reduce(0) { $0 &+ $1.key() } }
}
